import{_ as e,o,c as n,a5 as s}from"./chunks/framework.BjM_ivYE.js";const p=JSON.parse('{"title":"Cannot connect to the user PC","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/troubleshooting/user-pc-connection.md","filePath":"manual/troubleshooting/user-pc-connection.md","lastUpdated":1788840704000}'),a={name:"manual/troubleshooting/user-pc-connection.md"};function r(i,t,c,h,l,d){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="cannot-connect-to-the-user-pc" tabindex="-1">Cannot connect to the user PC <a class="header-anchor" href="#cannot-connect-to-the-user-pc" aria-label="Permalink to &quot;Cannot connect to the user PC&quot;">​</a></h1><p>NoMachine will not connect to the PC you work on directly. <strong>The U-PC and the AI PC are the same user PC</strong>, and the address is determined by <strong>where it sits</strong>, not by what it is called.</p><table tabindex="0"><thead><tr><th>Location</th><th>IP</th></tr></thead><tbody><tr><td><strong>Inside</strong> the robot</td><td><code>192.168.0.12</code></td></tr><tr><td><strong>Outside</strong> the robot</td><td><code>192.168.0.13</code></td></tr></tbody></table><p>The user PC is an option, so some robots do not have one.</p><h2 id="first-checks" tabindex="-1">First checks <a class="header-anchor" href="#first-checks" aria-label="Permalink to &quot;First checks {#first-checks}&quot;">​</a></h2><ul><li>Check whether the user PC sits <strong>inside or outside</strong> the robot, and connect to the matching address above.</li><li>Confirm the PC you are connecting from is on the <strong>same network</strong> as the robot — it must be connected to the robot&#39;s Wi-Fi (the name starts with <code>RBQ_</code>).</li><li>Confirm the user PC is powered on.</li></ul><h2 id="check-ip" tabindex="-1">The address differs from the table <a class="header-anchor" href="#check-ip" aria-label="Permalink to &quot;The address differs from the table {#check-ip}&quot;">​</a></h2><p><strong>Cause:</strong> If the user PC is using an address other than the one in the table, the connection fails.</p><p><strong>Fix:</strong></p><ol><li><strong>Connect a monitor directly to the user PC</strong> and check its current IP.</li><li>If it differs from the table, <strong>set it statically</strong> to the address matching its location.</li><li>Connect again with NoMachine.</li></ol><p>See <a href="/RBQ/manual/interface/network.html">Network Diagrams</a> for the robot&#39;s full IP layout.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>The Motion PC (<code>192.168.0.10</code>) runs the robot itself and is <strong>not user-accessible.</strong> Do your development work on the user PC.</p></div></div><h2 id="session-fails" tabindex="-1">The network is reachable but no desktop appears <a class="header-anchor" href="#session-fails" aria-label="Permalink to &quot;The network is reachable but no desktop appears {#session-fails}&quot;">​</a></h2><p><strong>Cause:</strong> NoMachine is not installed on the user PC, or its server is not running.</p><p><strong>Fix:</strong> Follow the installation and connection procedure below.</p><p><strong>→ <a href="/RBQ/software/release-note/how-to-connect-rbq-dev-pc.html">How to Connect to the RBQ Development PC</a></strong></p><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck? {#still-stuck}&quot;">​</a></h2><p>Tell us the IP you read from the monitor attached to the user PC, along with the error message shown when the connection fails.</p><p><strong>→ <a href="/RBQ/manual/support/">Contact us</a></strong></p>',19)])])}const b=e(a,[["render",r]]);export{p as __pageData,b as default};
